int counter = 0;

void setup() {
  Serial.begin(9600);                       // start the serial port at 9600 baud
  Serial.println("Hello from the ATmega128!");
}

void loop() {
  if (Serial.available() > 0) {             // a character was typed
    char c = Serial.read();
    Serial.print("You typed: ");
    Serial.println(c);
  }

  Serial.print("Count: ");
  Serial.println(counter);
  counter++;
  delay(1000);
}
